SELECT M.StockMovementID, M.MovementDate, M.MovementTypeID, MT.MovementTypeCode, MT.MovementTypeName, MT.StockEffect, M.ItemID, I.InternalSKU, I.ItemName, M.Quantity, M.FromLocationID, LFrom.LocationCode AS FromLocationCode, LFrom.LocationName AS FromLocationName, WFrom.WarehouseName AS FromWarehouseName, M.ToLocationID, LTo.LocationCode AS ToLocationCode, LTo.LocationName AS ToLocationName, WTo.WarehouseName AS ToWarehouseName, M.CustomerID, C.CustomerName, M.SalesOrderID, SO.SalesOrderNo, M.SalesOrderLineID, M.CustomerPOID, P.PONumber, M.CustomerPOLineID, M.InvoiceID, INV.InvoiceNo, M.InvoiceLineID, M.ReferenceDocument, M.SourceDocumentType, M.Reason, M.Notes, M.MovementNotes
FROM (((((((((T_StockMovements AS M LEFT JOIN T_StockMovementTypes AS MT ON M.MovementTypeID = MT.MovementTypeID) LEFT JOIN T_Items AS I ON M.ItemID = I.ItemID) LEFT JOIN T_Locations AS LFrom ON M.FromLocationID = LFrom.LocationID) LEFT JOIN T_Warehouses AS WFrom ON LFrom.WarehouseID = WFrom.WarehouseID) LEFT JOIN T_Locations AS LTo ON M.ToLocationID = LTo.LocationID) LEFT JOIN T_Warehouses AS WTo ON LTo.WarehouseID = WTo.WarehouseID) LEFT JOIN T_Customers AS C ON M.CustomerID = C.CustomerID) LEFT JOIN T_SalesOrders AS SO ON M.SalesOrderID = SO.SalesOrderID) LEFT JOIN T_CustomerPOs AS P ON M.CustomerPOID = P.CustomerPOID) LEFT JOIN T_Invoices AS INV ON M.InvoiceID = INV.InvoiceID
ORDER BY M.MovementDate DESC , M.StockMovementID DESC;

